<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:10px}h1{font-size:20px;margin:0}.muted{color:#64748b}.header{display:flex;justify-content:space-between;margin-bottom:24px}.summary{padding:12px;background:#f1f5f9;margin:14px 0}table{width:100%;border-collapse:collapse}th,td{padding:7px;border-bottom:1px solid #e2e8f0;text-align:left}th{font-size:8px;text-transform:uppercase;color:#64748b}.right{text-align:right}.total{font-weight:bold;border-top:2px solid #94a3b8}</style></head><body><div class="header"><div><h1>Supplier Statement</h1><p class="muted">{{ $company->legal_name ?: $company->name }}</p></div><div><strong>{{ $supplier->name }}</strong><br><span class="muted">{{ $from->format('d M Y') }} – {{ $to->format('d M Y') }}</span></div></div><div class="summary">Opening balance: ₹{{ number_format($statement['opening']/100,2) }}</div><table><thead><tr><th>Date</th><th>Reference</th><th>Description</th><th class="right">Debit</th><th class="right">Credit</th><th class="right">Balance</th></tr></thead><tbody>@foreach($statement['rows'] as $row)<tr><td>{{ $row['date'] }}</td><td>{{ $row['reference'] }}</td><td>{{ $row['description'] }}</td><td class="right">{{ number_format($row['debit']/100,2) }}</td><td class="right">{{ number_format($row['credit']/100,2) }}</td><td class="right">{{ number_format($row['balance']/100,2) }}</td></tr>@endforeach<tr class="total"><td colspan="5">Closing balance</td><td class="right">₹{{ number_format($statement['closing']/100,2) }}</td></tr></tbody></table></body></html>
